interface FocusState {
  /** Reference hours currently emphasised across the grid (hovered column or summary window). */
  hours: ReadonlySet<number>;
  focus: (hours: readonly number[]) => void;
  clear: () => void;
}

const EMPTY: ReadonlySet<number> = new Set();

