import { chromium } from "playwright-core";

const URL = "http://localhost:9388/";
const browser = await chromium.launch({ channel: "chrome", headless: true });
const errors = [];
const log = (...args) => console.log(...args);

const context = await browser.newContext({ viewport: { width: 1440, height: 1000 }, deviceScaleFactor: 2 });
await context.grantPermissions(["clipboard-read", "clipboard-write"], { origin: URL });
const page = await context.newPage();
page.on("console", (msg) => msg.type() === "error" && errors.push(msg.text()));
page.on("pageerror", (err) => errors.push(String(err)));
await page.goto(URL);

const grid = page.getByRole("table");
const summary = page.locator("[aria-label='Overlap summary']");
const rowNames = () => grid.getByRole("rowheader").evaluateAll((els) => els.map((el) => el.innerText.split("\n")[0]));
const summaryText = async () => (await summary.innerText()).replace(/\n+/g, " | ");

log("rows:", await rowNames());
log("overlap cells per row:", await grid.getByRole("row").evaluateAll((rows) =>
  rows.map((row) => [...row.querySelectorAll("[role=cell][aria-label$='overlap']")].map((c) => c.dataset.hour).join(",")),
));

// Column hover
await grid.locator("[data-hour='7']").first().hover();
await page.locator("section[aria-label='Timezone grid']").screenshot({ path: ".qa/hover-col.png" });

// Badge hover + copy
const badge = summary.getByRole("button").first();
await badge.hover();
await page.locator("section[aria-label='Timezone grid']").screenshot({ path: ".qa/hover-badge.png" });
await badge.click();
log("clipboard:\n" + (await page.evaluate(() => navigator.clipboard.readText())));
log("badge after click:", await badge.innerText());

// Base mode
await page.getByRole("radio", { name: "Base" }).click();
await page.waitForTimeout(400);
log("base summary:", await summaryText());
await page.screenshot({ path: ".qa/base.png", fullPage: true });

// Add Kathmandu via search
const combo = page.getByRole("combobox", { name: "Add a city" });
await combo.click();
await page.screenshot({ path: ".qa/picker-open.png" });
await combo.fill("kath");
await combo.press("Enter");
await page.waitForTimeout(400);
log("after adding kath:", await rowNames());

// Duplicate attempt: Denpasar via alias "bali"
await combo.fill("bali");
const option = page.getByRole("option").first();
log("bali option:", (await option.innerText()).replace(/\n/g, " / "), "| aria-disabled:", await option.getAttribute("aria-disabled"));
await combo.press("Enter");
await option.click();
await combo.press("Escape");
log("after dup attempt:", await rowNames());

// Search by country
await combo.fill("japan");
log("japan ->", await page.getByRole("option").allInnerTexts());
await combo.press("Enter");
await page.waitForTimeout(300);

// Promote Geneva
await grid.getByRole("button", { name: "Geneva" }).click();
await page.waitForTimeout(400);
log("after promote Geneva:", await rowNames());
log("REF badge on:", await grid.getByRole("row").filter({ hasText: "REF" }).getByRole("rowheader").innerText());
log("base summary (Geneva ref):", await summaryText());

// Remove Denpasar
await page.getByRole("button", { name: "Remove Denpasar" }).click();
await page.waitForTimeout(400);
log("after remove:", await rowNames());

// Overnight + 24h
await page.getByLabel("Wake up").selectOption("22");
await page.getByLabel("Sleep").selectOption("6");
await page.getByRole("radio", { name: "24h" }).click();
await page.getByRole("radio", { name: "Meeting" }).click();
await page.waitForTimeout(400);
log("overnight 24h meeting summary:", await summaryText());
await page.screenshot({ path: ".qa/overnight-24h.png", fullPage: true });

// Zero overlap: 9-17 with Geneva, SF, Kathmandu, Tokyo
await page.getByLabel("Wake up").selectOption("9");
await page.getByLabel("Sleep").selectOption("17");
await page.waitForTimeout(300);
