            <div
              className="absolute -top-1 -bottom-1 w-0.5 -translate-x-1/2 rounded-full bg-now shadow-[0_0_0_1.5px_var(--surface)]"
              style={{ left: pct(nowHours) }}
            />
          )}
        </div>
      </div>
    </div>
