    expect(formatClock(16 * 60, "24h")).toBe("16:00");
    expect(formatCellLabel(14 * 60 + 45, "12h")).toEqual({ value: "2:45", suffix: "pm" });
    expect(formatCellLabel(0, "24h")).toEqual({ value: "00", suffix: "" });
    expect(formatCellLabel(9 * 60 + 45, "24h")).toEqual({ value: "09", suffix: ":45" });
  });

