    expect(formatUtcOffset(-7 * 60)).toBe("UTC−7");
    expect(formatUtcOffset(5 * 60 + 45)).toBe("UTC+5:45");
    expect(formatUtcOffset(0)).toBe("UTC+0");
    expect(formatOffsetDiff(15 * 60)).toBe("+15h");
    expect(formatOffsetDiff(-(3 * 60 + 30))).toBe("−3h 30m");
  });
});

