              <span
                key={hour}
                className={cn(
                  "absolute bottom-1.5 -translate-x-1/2 font-mono text-[10.5px] text-ink-3 transition-opacity tabular",
                  hoveredHour !== undefined && Math.abs(hoveredHour - hour) < 2 && "opacity-0",
                )}
                style={{ left: pct(hour + 0.5) }}
              >
                {formatHour(hour, format)}
