import { chromium } from "playwright-core";

const URL = "http://localhost:9388/";
const browser = await chromium.launch({ channel: "chrome", headless: true });
const errors = [];
const seed = {
  state: { cityIds: ["san-francisco", "geneva", "mumbai", "kathmandu", "tokyo", "sao-paulo"], mode: "meeting", wakeHour: 7, sleepHour: 23, timeFormat: "24h" },
  version: 1,
};

async function open(opts, withSeed = false) {
  const context = await browser.newContext(opts);
  if (withSeed) {
    await context.addInitScript((value) => {
      if (!sessionStorage.getItem("seeded")) {
        localStorage.setItem("tz-overlap:preferences", value);
        sessionStorage.setItem("seeded", "1");
      }
    }, JSON.stringify(seed));
  }
  const page = await context.newPage();
  page.on("console", (msg) => msg.type() === "error" && errors.push(msg.text()));
  page.on("pageerror", (err) => errors.push(String(err)));
  await page.goto(URL);
  await page.waitForLoadState("networkidle");
  return page;
}

// Dropdown, after animation
const d = await open({ viewport: { width: 1440, height: 1000 }, deviceScaleFactor: 2 });
await d.getByRole("combobox", { name: "Add a city" }).click();
await d.waitForTimeout(300);
await d.screenshot({ path: ".qa/picker-open.png", clip: { x: 600, y: 300, width: 840, height: 700 } });
await d.getByRole("combobox", { name: "Add a city" }).fill("in");
await d.waitForTimeout(300);
await d.screenshot({ path: ".qa/picker-search.png", clip: { x: 600, y: 300, width: 840, height: 700 } });

// 24h with fractional zones
const f = await open({ viewport: { width: 1440, height: 1000 }, deviceScaleFactor: 2 }, true);
await f.locator("section[aria-label='Timezone grid']").screenshot({ path: ".qa/grid-24h.png" });

// Breakpoints
for (const width of [768, 767, 1024]) {
  const p = await open({ viewport: { width, height: 900 }, deviceScaleFactor: 2 });
  const layout = (await p.getByRole("table").count()) ? "desktop table" : "mobile columns";
  console.log(width, "→", layout);
  await p.screenshot({ path: `.qa/w${width}.png`, fullPage: true });
}

// Mobile with many cities
const m = await open({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 3, isMobile: true, hasTouch: true }, true);
await m.screenshot({ path: ".qa/mobile-many.png", fullPage: true });
const scroller = m.locator("div[class*='overflow-x-auto']").first();
await scroller.evaluate((el) => (el.scrollLeft = 200));
await m.evaluate(() => window.scrollTo(0, 900));
await m.waitForTimeout(200);
const sync = await m.evaluate(() => {
  const header = document.querySelector("div.sticky.overflow-hidden");
  const body = document.querySelector("div[class*='overflow-x-auto']");
  return { header: header?.scrollLeft, body: body?.scrollLeft, headerTop: header?.getBoundingClientRect().top };
});
console.log("mobile scroll sync:", sync);
await m.getByRole("listitem").nth(12).tap();
await m.waitForTimeout(150);
await m.screenshot({ path: ".qa/mobile-scrolled.png" });

const md = await open({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 3, isMobile: true, hasTouch: true, colorScheme: "dark" });
await md.screenshot({ path: ".qa/mobile-dark.png", fullPage: true });

console.log("errors:", errors);
await browser.close();

