cat > .qa/keys.mjs <<'EOF'
import { chromium } from "playwright-core";
const browser = await chromium.launch({ channel: "chrome", headless: true });
const ctx = await browser.newContext({ viewport: { width: 1440, height: 1000 }, deviceScaleFactor: 2 });
const p = await ctx.newPage();
const errors = [];
p.on("pageerror", (e) => errors.push(String(e)));
p.on("console", (m) => m.type() === "error" && errors.push(m.text()));
await p.goto("http://localhost:9388/");
await p.waitForLoadState("networkidle");
const names = () => p.getByRole("table").getByRole("rowheader").evaluateAll((els) => els.map((el) => el.innerText.split("\n")[0]));

await p.keyboard.press("/");
console.log("focused after '/':", await p.evaluate(() => document.activeElement?.getAttribute("aria-label")));
await p.keyboard.type("lon");
await p.keyboard.press("ArrowDown");
console.log("active option:", await p.evaluate(() => document.getElementById(document.activeElement.getAttribute("aria-activedescendant"))?.dataset.cityId));
await p.keyboard.press("ArrowUp");
await p.keyboard.press("Enter");
await p.waitForTimeout(350);
console.log("after keyboard add:", await names());
await p.keyboard.press("Escape");

// Arrow keys on segmented control
await p.getByRole("radio", { name: "Meeting" }).focus();
await p.keyboard.press("ArrowRight");
await p.waitForTimeout(350);
console.log("mode after ArrowRight:", await p.getByRole("radio", { checked: true }).first().innerText());

// Remove down to one, then zero
for (const city of ["London", "Geneva", "Denpasar"]) {
  await p.getByRole("button", { name: `Remove ${city}` }).click();
  await p.waitForTimeout(320);
}
console.log("one city summary:", await p.locator("[aria-label='Overlap summary']").innerText());
await p.screenshot({ path: ".qa/one-city.png", fullPage: true });
await p.getByRole("button", { name: "Remove San Francisco" }).click();
await p.waitForTimeout(320);
console.log("zero city summary:", await p.locator("[aria-label='Overlap summary']").innerText());
console.log("table present:", await p.getByRole("table").count());
await p.screenshot({ path: ".qa/zero-city.png", fullPage: true });
await p.reload();
console.log("zero persisted after reload:", await p.getByRole("table").count() === 0);
await p.getByRole("button", { name: "Reset to defaults" }).click();
await p.waitForTimeout(350);
console.log("after reset:", await names(), await p.getByRole("radio", { checked: true }).allInnerTexts());
console.log("errors:", errors);
await browser.close();
EOF
